E = html.escape


def tabla(cabecera, filas):
    return '<div class="tabla"><table><thead><tr>'+''.join('<th>'+E(c)+'</th>' for c in cabecera)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in fila)+'</tr>' for fila in filas)+'</tbody></table></div>'


def lista(*items):
    return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'


def caja(titulo, texto, clase=''):
    return '<article class="tarjeta '+clase+'"><h3>'+titulo+'</h3><p>'+texto+'</p></article>'


def codigo(texto):
    return '<pre><code>'+E(texto)+'</code></pre>'


def inventario():
    p = RAIZ/'scripts/generar_entrega_ti.py'
    spec = importlib.util.spec_from_file_location('inventario_estatico', p)
    modulo = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(modulo)
    inv = modulo.inventario()
    version = re.search(r"VERSION_FRONTEND='([^']+)'", (RAIZ/'scripts/versionar_frontend.mjs').read_text()).group(1)
    inv.update(versionFrontend=version, fecha='2026-10-27', revisionCodigo=REVISION,
        alcance='Inventario estático del código de referencia v69. No es una consulta al servidor productivo.')
    return inv


