def arquitectura():
    return '<div class="arquitectura">'+''.join('<div class="nodo"><span class="eyebrow">'+a+'</span><strong>'+b+'</strong><small>'+c+'</small></div>' for a,b,c in [
        ('01 · Acceso','PC / handheld','Navegador · HTTPS · /app/'),
        ('02 · Entrada','Apache2 · 8443','Receptor del puerto publicado'),
        ('03 · Aplicación','Uvicorn · 3002','FastAPI · reglas y API'),
        ('04 · Datos','MySQL','SQLAlchemy + PyMySQL · transacciones')])+'</div>'


